class MyTask implements Runnable {
    public void run() {
        System.out.println("praca w watku: " + Thread.currentThread().getName());
    }
}
Runnable zadanie = new MyTask();
Thread watek = new Thread(zadanie, "Watek-Runnable-A");
watek.start();
watek.join();

Runnable wspolneZadanie = new MyTask();
Thread watekX = new Thread(wspolneZadanie, "Watek-X");
Thread watekY = new Thread(wspolneZadanie, "Watek-Y");
watekX.start();
watekY.start();
watekX.join();
watekY.join();
// Ten sam Runnable, ale rozne watki - obie linie wypisza rozna nazwe watku

class PriorytetowaneZadanie implements Runnable, Comparable<PriorytetowaneZadanie> {
    int priorytet;
    public void run() { /* praca */ }
    public int compareTo(PriorytetowaneZadanie inne) {
        return Integer.compare(this.priorytet, inne.priorytet);
    }
}
// Niemozliwe do osiagniecia tak prosto przez extends Thread - Comparable to DRUGI interfejs obok Runnable

