class UnsafeCounter implements Runnable {
    int sharedCounter = 0;
    public void run() { for (int i=0;i<1000;i++) sharedCounter++; }
}
UnsafeCounter c = new UnsafeCounter();
Thread t1 = new Thread(c), t2 = new Thread(c);
t1.start(); t2.start(); t1.join(); t2.join();
System.out.println(c.sharedCounter); // czesto < 2000, race condition!

