class RetryTask implements Runnable {
    int proby = 0;
    public void run() {
        proby++;
        if (proby == 1) System.out.println("blad przy probie " + proby);
        else System.out.println("sukces przy probie " + proby);
    }
}
RetryTask task = new RetryTask();
new Thread(task).start(); // proba 1: blad
// ... join, potem:
new Thread(task).start(); // proba 2: sukces

